import asyncio

async def check_service(name: str, delay: float) -> str:
    await asyncio.sleep(delay)  # stand-in for awaitable network I/O
    return f'{name}: healthy'

async def main() -> None:
    tasks = [
        asyncio.create_task(check_service('catalog', 0.01)),
        asyncio.create_task(check_service('billing', 0.02)),
    ]
    try:
        results = await asyncio.wait_for(asyncio.gather(*tasks), timeout=1.0)
    except TimeoutError:
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise
    else:
        for result in results:
            print(result)

asyncio.run(main())
